  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Skagen', 'Půvabné rybářské a malířské městečko se žlutými domky a zvláštním severským světlem, jež lákalo umělce. Srdce nejsevernějšího Jutska.', 57.7211, 10.5836, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skagen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skagen.jpg"}'::text[], 0),
    (v_route, 'Grenen', 'Písečná kosa na samém cípu Dánska, kde se srážejí vlny Severního a Baltského moře. Symbolický konec pevniny.', 57.7444, 10.6633, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grenen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grenen.jpg"}'::text[], 1),
    (v_route, 'Råbjerg Mile', 'Největší putující písečná duna severní Evropy, pomalu se sunoucí krajinou. Ojedinělý přírodní úkaz.', 57.6014, 10.3944, 'https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A5bjerg_Mile.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%A5bjerg_Mile.jpg"}'::text[], 2),
    (v_route, 'Zapískovaný kostel', 'Věž kostela zaváta pískem, jediné, co zbylo po zaniklém kostele u Skagenu. Připomínka síly písečných dun.', 57.7239, 10.5406, 'https://commons.wikimedia.org/wiki/Special:FilePath/Den_Tilsandede_Kirke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Den_Tilsandede_Kirke.jpg"}'::text[], 3),
    (v_route, 'Maják Rubjerg Knude', 'Osamělý maják na okraji písečného útesu, jenž musel být kvůli erozi přesunut. Dramatická scenérie západního pobřeží.', 57.4494, 9.7756, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rubjerg_Knude_Fyr.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rubjerg_Knude_Fyr.jpg"}'::text[], 4);
