  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ringkøbing', 'Půvabné městečko na břehu stejnojmenného fjordu s dlážděným náměstím. Klidná zastávka u vody na západě.', 56.09, 8.2436, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ringk%C3%B8bing.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ringk%C3%B8bing.jpg"}'::text[], 0),
    (v_route, 'Hvide Sande', 'Rušný rybářský přístav na úzké kose mezi fjordem a mořem, ráj surfařů. Zastávka na čerstvé ryby.', 55.9992, 8.1258, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hvide_Sande.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hvide_Sande.jpg"}'::text[], 1),
    (v_route, 'Blåvand a maják', 'Nejzápadnější bod Dánska s majákem, dunami a betonovými bunkry proměněnými v umění. Nekonečné pláže.', 55.5578, 8.0794, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bl%C3%A5vand.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bl%C3%A5vand.jpg"}'::text[], 2),
    (v_route, 'Bovbjerg Fyr', 'Červený maják na jílovém útesu nad Severním mořem s výhledem na pobřeží. Ikonická zastávka západu.', 56.5303, 8.1706, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bovbjerg_Fyr.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bovbjerg_Fyr.jpg"}'::text[], 3),
    (v_route, 'Tipperne', 'Ptačí rezervace na jižním konci fjordu Ringkøbing, ráj tažného ptactva. Klidné místo pro milovníky přírody.', 55.85, 8.22, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tipperne.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tipperne.jpg"}'::text[], 4);
