  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Møns Klint', 'Oslnivě bílé křídové útesy vysoké až 128 m padající do tyrkysového Baltu. Nejdramatičtější pobřeží Dánska.', 54.9694, 12.5411, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%B8ns_Klint.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%B8ns_Klint.jpg"}'::text[], 0),
    (v_route, 'Stege', 'Hlavní městečko ostrova Møn se středověkou bránou a přístavem. Klidná zastávka s dánskou atmosférou.', 54.9856, 12.2842, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stege.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stege.jpg"}'::text[], 1),
    (v_route, 'Kostel Elmelunde', 'Bílý kostel s proslulými středověkými freskami mistra z Elmelunde. Klenot ostrovní gotiky.', 54.9639, 12.42, 'https://commons.wikimedia.org/wiki/Special:FilePath/Elmelunde_Kirke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Elmelunde_Kirke.jpg"}'::text[], 2),
    (v_route, 'Liselund', 'Romantický zámeček s doškovou střechou v anglickém parku u útesů. Idylická zastávka mezi stromy.', 54.9756, 12.5203, 'https://commons.wikimedia.org/wiki/Special:FilePath/Liselund.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Liselund.jpg"}'::text[], 3),
    (v_route, 'GeoCenter Møns Klint', 'Moderní návštěvnické centrum vysvětlující vznik útesů a geologii ostrova. Vhodné i za nepohody.', 54.97, 12.53, 'https://commons.wikimedia.org/wiki/Special:FilePath/GeoCenter_M%C3%B8ns_Klint.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GeoCenter_M%C3%B8ns_Klint.jpg"}'::text[], 4);
