  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Egeskov', 'Nejlépe zachovaný renesanční vodní zámek Evropy, obklopený zahradami a bludišti. Pohádková dominanta Fynu.', 55.1747, 10.42, 'https://commons.wikimedia.org/wiki/Special:FilePath/Egeskov_Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Egeskov_Castle.jpg"}'::text[], 0),
    (v_route, 'Odense – dům H. C. Andersena', 'Rodné město slavného pohádkáře s dlážděnými uličkami a muzeem. Srdce ostrova plné historie.', 55.3959, 10.3883, 'https://commons.wikimedia.org/wiki/Special:FilePath/Odense.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Odense.jpg"}'::text[], 1),
    (v_route, 'Svendborg', 'Živý přístav na jihu Fynu, výchozí bod k jižním ostrůvkům. Příjemná zastávka u vody.', 55.0603, 10.6108, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svendborg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svendborg.jpg"}'::text[], 2),
    (v_route, 'Faaborg', 'Půvabné historické městečko se žlutými domky a zvonicí na jihozápadě ostrova. Idylická zastávka.', 55.0958, 10.2417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Faaborg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Faaborg.jpg"}'::text[], 3),
    (v_route, 'Ostrov Ærø – Ærøskøbing', 'Trajektem dostupné pohádkové městečko s dlážděnými uličkami a barevnými domky. Skok mimo čas.', 54.8867, 10.4108, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%86r%C3%B8sk%C3%B8bing.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%86r%C3%B8sk%C3%B8bing.jpg"}'::text[], 4);
