  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Kronborg', 'Renesanční pevnost v Helsingøru, kulisa Shakespearova Hamleta, UNESCO památka. Střeží úžinu Øresund proti Švédsku.', 56.0389, 12.6214, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kronborg_Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kronborg_Castle.jpg"}'::text[], 0),
    (v_route, 'Zámek Frederiksborg', 'Nádherný renesanční vodní zámek v Hillerødu, dnes muzeum národních dějin. Nejfotogeničtější zámek Dánska.', 55.935, 12.3006, 'https://commons.wikimedia.org/wiki/Special:FilePath/Frederiksborg_Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Frederiksborg_Castle.jpg"}'::text[], 1),
    (v_route, 'Katedrála Roskilde', 'Cihlová katedrála UNESCO, pohřebiště dánských králů po staletí. Impozantní gotická stavba.', 55.6417, 12.0797, 'https://commons.wikimedia.org/wiki/Special:FilePath/Roskilde_Cathedral.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Roskilde_Cathedral.jpg"}'::text[], 2),
    (v_route, 'Muzeum vikingských lodí Roskilde', 'Muzeum s originály vikingských lodí vyzdvižených z fjordu a živou loděnicí. Skvělý pohled do dějin.', 55.6533, 12.0839, 'https://commons.wikimedia.org/wiki/Special:FilePath/Viking_Ship_Museum_Roskilde.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Viking_Ship_Museum_Roskilde.jpg"}'::text[], 3),
    (v_route, 'Dyrehaven', 'Královská obora se stády jelenů a loveckým zámečkem u Kodaně. Klidná zastávka v přírodě.', 55.7889, 12.5644, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dyrehaven.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dyrehaven.jpg"}'::text[], 4);
