  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zřícenina Hammershus', 'Největší středověká zřícenina severní Evropy na skalnatém útesu nad mořem. Symbol Bornholmu.', 55.2731, 14.7597, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hammershus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hammershus.jpg"}'::text[], 0),
    (v_route, 'Rønne', 'Hlavní město a přístav ostrova s barevnými domky a dlážděnými uličkami. Brána Bornholmu.', 55.1, 14.7, 'https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%B8nne.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%B8nne.jpg"}'::text[], 1),
    (v_route, 'Gudhjem', 'Malebné rybářské městečko na skalnatém svahu proslulé uzenými sledi. Nejhezčí zastávka pobřeží.', 55.2117, 14.98, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gudhjem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gudhjem.jpg"}'::text[], 2),
    (v_route, 'Kulatý kostel Østerlars', 'Největší z proslulých kulatých kostelů Bornholmu, sloužících i jako pevnost. Ojedinělá románská stavba.', 55.15, 14.95, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%98sterlars_Kirke.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%98sterlars_Kirke.jpg"}'::text[], 3),
    (v_route, 'Skály Helligdomsklipperne', 'Dramatické žulové útesy nad mořem na severním pobřeží ostrova. Působivá scenérie a stezky.', 55.23, 14.87, 'https://commons.wikimedia.org/wiki/Special:FilePath/Helligdomsklipperne.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Helligdomsklipperne.jpg"}'::text[], 4);
