  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ebeltoft', 'Kouzelné historické městečko s doškovými domky, nejmenší radnicí a starou fregatou Jylland. Perla Djurslandu.', 56.1948, 10.6772, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ebeltoft.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ebeltoft.jpg"}'::text[], 0),
    (v_route, 'Národní park Mols Bjerge', 'Zvlněná ledovcová krajina s kopci, vřesovišti a výhledy na moře. Ráj klidných silnic a přírody.', 56.2258, 10.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mols_Bjerge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mols_Bjerge.jpg"}'::text[], 1),
    (v_route, 'Fregata Jylland', 'Nejdelší dřevěná válečná loď světa v suchém doku v Ebeltoftu. Fascinující námořní památka.', 56.19, 10.68, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fregatten_Jylland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fregatten_Jylland.jpg"}'::text[], 2),
    (v_route, 'Kalø Slotsruin', 'Zřícenina hradu na ostrůvku spojeném s pevninou dlážděnou cestou. Romantická zastávka u moře.', 56.29, 10.48, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kal%C3%B8_Slotsruin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kal%C3%B8_Slotsruin.jpg"}'::text[], 3),
    (v_route, 'Grenaa – pláž', 'Široká písečná pláž na východním cípu poloostrova, oblíbené letovisko. Zastávka na koupání.', 56.4139, 10.88, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grenaa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grenaa.jpg"}'::text[], 4);
