  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ribe', 'Nejstarší město Dánska s katedrálou, křivolakými uličkami a čapími hnízdy. Živoucí středověká atmosféra.', 55.3277, 8.7683, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ribe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ribe.jpg"}'::text[], 0),
    (v_route, 'Møgeltønder', 'Pohádková vesnice s dlážděnou lipovou alejí a zámkem, kde bydlí dánská princezna. Jedna z nejhezčích uliček země.', 54.9358, 8.7906, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%B8gelt%C3%B8nder.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%B8gelt%C3%B8nder.jpg"}'::text[], 1),
    (v_route, 'Tønder', 'Historické město proslulé krajkami a starobylými domy u německé hranice. Klidná zastávka na jihu.', 54.9364, 8.8628, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%B8nder.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C3%B8nder.jpg"}'::text[], 2),
    (v_route, 'Vadehavet – slapové moře', 'UNESCO chráněné slapové moře s obřími hejny ptáků a jevem sort sol. Ojedinělý přírodní zážitek.', 55.15, 8.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vadehavet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vadehavet.jpg"}'::text[], 3),
    (v_route, 'Mandø', 'Ostrůvek dostupný jen za odlivu po dně moře, oáza klidu a ptactva. Dobrodružná zastávka.', 55.28, 8.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mand%C3%B8.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mand%C3%B8.jpg"}'::text[], 4);
