  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Aalborg', 'Živé město na břehu Limfjordu s renesančními domy a moderním nábřežím. Kulturní srdce severu.', 57.0488, 9.9217, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aalborg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aalborg.jpg"}'::text[], 0),
    (v_route, 'Ostrov Mors – Molerové útesy', 'Ostrov uprostřed Limfjordu s jílovými útesy plnými zkamenělin. Geologicky ojedinělé místo.', 56.7975, 8.86, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mors.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mors.jpg"}'::text[], 1),
    (v_route, 'Národní park Thy', 'První dánský národní park s dunami, vřesovišti a divokým pobřežím Severního moře. Nejdivočejší kout země.', 56.9558, 8.6942, 'https://commons.wikimedia.org/wiki/Special:FilePath/Thy_National_Park.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Thy_National_Park.jpg"}'::text[], 2),
    (v_route, 'Fur', 'Malý ostrov proslulý molerovými útesy a klidnou idylou. Skok mimo civilizaci.', 56.82, 9.02, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fur.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fur.jpg"}'::text[], 3),
    (v_route, 'Spøttrup Borg', 'Nejlépe zachovaný středověký vodní hrad Dánska s příkopy a valy. Působivá pevnost u fjordu.', 56.63, 8.93, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sp%C3%B8ttrup_Borg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sp%C3%B8ttrup_Borg.jpg"}'::text[], 4);
