  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Stevns Klint', 'Vápencové útesy UNESCO se stopou dopadu meteoritu, jenž vyhubil dinosaury, a kostelem na hraně. Ojedinělá geologická památka.', 55.2894, 12.45, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stevns_Klint.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stevns_Klint.jpg"}'::text[], 0),
    (v_route, 'Køge', 'Historické přístavní město s náměstím a hrázděnými domy jižně od Kodaně. Příjemná výchozí zastávka.', 55.4581, 12.1836, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B8ge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B8ge.jpg"}'::text[], 1),
    (v_route, 'Store Heddinge', 'Městečko s ojedinělým osmibokým románským kostelem uprostřed poloostrova Stevns. Klidná zastávka.', 55.3125, 12.3894, 'https://commons.wikimedia.org/wiki/Special:FilePath/Store_Heddinge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Store_Heddinge.jpg"}'::text[], 2),
    (v_route, 'Vallø Slot', 'Renesanční vodní zámek s věžemi obklopený parkem a lesy. Romantická zastávka mimo hlavní tahy.', 55.41, 12.23, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vall%C3%B8_Slot.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vall%C3%B8_Slot.jpg"}'::text[], 3),
    (v_route, 'Pevnost Stevnsfort', 'Studenoválečná podzemní pevnost vytesaná do vápence útesů. Fascinující vojenská památka.', 55.2894, 12.45, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stevnsfort.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stevnsfort.jpg"}'::text[], 4);
